{
                "type": "object",
                "properties": {
                    "city": {
                        "type": "string",
                        "description": "The city name to get weather for"
                    }
                },
                "required": ["city"]
            }

# 模拟天气查询 - 实际实现应该调用天气API try: city = arguments.get('city', 'Unknown') # 模拟不同的天气响应 import random weather_conditions = ['sunny', 'cloudy', 'rainy', 'snowy'] temperatures = { 'Beijing': random.randint(-5, 35), 'Shanghai': random.randint(5, 38), 'Guangzhou': random.randint(15, 40), 'Shenzhen': random.randint(18, 38) }
temperature = temperatures.get(city, random.randint(-10, 40)) condition = random.choice(weather_conditions)
result = { 'city': city, 'temperature': temperature, 'condition': condition, 'unit': 'celsius', 'humidity': f"{random.randint(30, 90)}%", 'wind_speed': f"{random.randint(0, 30)} km/h" } except Exception as e: result = f"Weather query failed: {str(e)}"

# Simple calculator implementation
try:
    # Security: Only allow basic math operations
    allowed_chars = set('0123456789+-*/.() ')
    if not all(c in allowed_chars for c in arguments['expression']):
        result = "Error: Only basic math operations are allowed"
    else:
        # Use eval with limited globals and locals for safety
        result = eval(arguments['expression'], {'__builtins__': {}}, {})
except ZeroDivisionError:
    result = "Error: Division by zero"
except Exception as e:
    result = f"Error: {str(e)}"

{
                "type": "object",
                "properties": {
                    "recipients": {
                        "type": "array",
                        "items": {"type": "string"},
                        "description": "List of email addresses"
                    },
                    "subject": {
                        "type": "string",
                        "description": "Email subject"
                    },
                    "body": {
                        "type": "string",
                        "description": "Email body content"
                    }
                },
                "required": ["recipients", "subject", "body"]
            }

# 模拟发送邮件功能
try:
    recipients = arguments.get('recipients', [])
    subject = arguments.get('subject', 'No Subject')
    body = arguments.get('body', '')

    # 模拟发送邮件
    result = {
        'success': True,
        'message': f"Email sent to {', '.join(recipients)}",
        'subject': subject,
        'recipients_count': len(recipients)
    }
except Exception as e:
    result = {
        'success': False,
        'error': f"Failed to send email: {str(e)}"
    }

{
                "type": "object",
                "properties": {
                    "search_term": {
                        "type": "string",
                        "description": "Product name or description to search for"
                    },
                    "limit": {
                        "type": "number",
                        "description": "Maximum number of results (default: 10)"
                    }
                },
                "required": ["search_term"]
            }

# 模拟产品搜索功能
try:
    search_term = arguments.get('search_term', '')
    limit = arguments.get('limit', 10)

    # 模拟产品数据
    sample_products = [
        {'id': 1, 'name': 'Laptop Computer', 'price': 999.99, 'category': 'Electronics'},
        {'id': 2, 'name': 'Wireless Mouse', 'price': 29.99, 'category': 'Electronics'},
        {'id': 3, 'name': 'Office Chair', 'price': 199.99, 'category': 'Furniture'},
        {'id': 4, 'name': 'Desk Lamp', 'price': 49.99, 'category': 'Home'},
        {'id': 5, 'name': 'Notebook', 'price': 9.99, 'category': 'Stationery'}
    ]

    # 模拟搜索逻辑
    matched_products = [
        product for product in sample_products 
        if search_term.lower() in product['name'].lower()
    ][:limit]

    result = {
        'search_term': search_term,
        'found_count': len(matched_products),
        'products': matched_products
    }
except Exception as e:
    result = f"Product search failed: {str(e)}"

[
    {
        "type": "llm_call",
        "name": "Welcome Message",
        "prompt_template": "Send a welcome message to our new customer: {{customer_name}}. They signed up for our {{service_tier}} service. Include information about next steps and how to get started.",
        "data_extraction": {
            "extract_json": true
        }
    },
    {
        "type": "tool_call",
        "name": "Send Welcome Email",
        "tool_name": "send_email",
        "arguments": {
            "recipients": ["{{customer_email}}"],
            "subject": "Welcome to DemoTech Solutions - {{service_tier}}",
            "body": "{{welcome_message}}"
        },
        "output_key": "email_result"
    },
    {
        "type": "condition",
        "name": "Check Service Tier",
        "condition": "{{service_tier}} == 'premium'",
        "true_branch": [
            {
                "type": "llm_call",
                "name": "Schedule Premium Onboarding",
                "prompt_template": "Create a personalized onboarding message for our premium customer {{customer_name}}. Offer to schedule a 1-on-1 onboarding session and mention the dedicated account manager.",
                "data_extraction": {
                    "extract_json": true
                }
            }
        ],
        "false_branch": [
            {
                "type": "llm_call",
                "name": "Standard Onboarding Info",
                "prompt_template": "Provide standard onboarding information for {{customer_name}} including documentation links and community support options.",
                "data_extraction": {
                    "extract_json": true
                }
            }
        ]
    }
]

{
    "type": "object",
    "properties": {
        "customer_name": {
            "type": "string",
            "description": "Full name of the customer"
        },
        "customer_email": {
            "type": "string",
            "description": "Email address of the customer"
        },
        "service_tier": {
            "type": "string",
            "enum": ["basic", "pro", "premium"],
            "description": "Service tier the customer signed up for"
        }
    },
    "required": ["customer_name", "customer_email", "service_tier"]
}

[
    {
        "type": "llm_call",
        "name": "Analyze Lead Information",
        "prompt_template": "Analyze this sales lead and determine their potential: Company: {{company_name}}, Industry: {{industry}}, Employee Count: {{employee_count}}, Budget: {{budget_range}}, Timeline: {{timeline}}. Provide a qualification score (1-10) and recommended next steps.",
        "data_extraction": {
            "extract_json": true
        }
    },
    {
        "type": "condition",
        "name": "Check Qualification Score",
        "condition": "{{qualification_score}} >= 7",
        "true_branch": [
            {
                "type": "llm_call",
                "name": "Create High Priority Response",
                "prompt_template": "Create a personalized response for this high-potential lead (score: {{qualification_score}}). Offer a product demo and mention relevant case studies from their industry ({{industry}}).",
                "data_extraction": {
                    "extract_json": true
                }
            },
            {
                "type": "tool_call",
                "name": "Schedule Follow-up",
                "tool_name": "send_email",
                "arguments": {
                    "recipients": ["{{lead_email}}"],
                    "subject": "Follow-up on your inquiry - {{company_name}}",
                    "body": "{{high_priority_response}}"
                }
            }
        ],
        "false_branch": [
            {
                "type": "llm_call",
                "name": "Create Nurture Sequence",
                "prompt_template": "Create a nurturing email for this lead (score: {{qualification_score}}). Provide educational content and invite them to upcoming webinars. Be helpful but not pushy.",
                "data_extraction": {
                    "extract_json": true
                }
            }
        ]
    }
]

